// 命令仅选择当前作者提议或原开课，不接受客户端指定师生/费用/掌握结果。
#include "resident/domains/growth/growth_tactic_lesson_commands.hpp"
#include <iostream>
#include <stdexcept>
using namespace hanmo::resident;
int main(){Integer checks=0;auto check=[&](bool ok,const char* label){++checks;if(!ok)throw std::runtime_error(label);};try{using V=BoundaryValue;using namespace boundary;auto p=obj({{"definition_id",V{"lesson"}}});auto start=decode_growth_tactic_lesson_command("tactic_lesson_start",p);check(start.ok&&start.value.definition_id=="lesson"&&start.value.started_fact_id.empty(),"exact start");check(compare_boundary(p,encode_growth_tactic_lesson_command(start.value)).exact(),"start exact roundtrip");p=obj({{"started_fact_id",V{"tactic_lesson:7"}}});auto stop=decode_growth_tactic_lesson_command("tactic_lesson_cancel",p);check(stop.ok&&stop.value.started_fact_id=="tactic_lesson:7","exact cancel");check(compare_boundary(p,encode_growth_tactic_lesson_command(stop.value)).exact(),"cancel exact roundtrip");p.as<V::Dict>()->emplace_back("started_fact_id",V{"tactic_lesson:8"});check(!decode_growth_tactic_lesson_command("tactic_lesson_cancel",p).ok,"duplicate before first match");check(!decode_growth_tactic_lesson_command("tactic_lesson_start",obj({{"definition_id",V{"lesson"}},{"teacher_actor_id",V{"other"}}})).ok,"caller cannot choose teacher");check(!decode_growth_tactic_lesson_command("tactic_lesson_start",obj({{"definition_id",V{""}}})).ok,"empty selection");check(!decode_growth_tactic_lesson_command("tactic_lesson_learn",obj({})).ok,"no free learn command");std::cout<<"GROWTH_TACTIC_LESSON_COMMANDS "<<checks<<" checks 0 failures\n";return 0;}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
